(ROOT/'verification/task_metrics_results.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');res={'status':'post_primary_descriptive','plan_commit':PLAN,'analysis_commit':ANALYSIS,'rows':4000,'max_cross_seed_mean_fidelity_difference':maxfid,'max_cross_seed_mean_normalized_energy_difference':maxenergy,'paths':{'summary':'results/task_metrics/prepared_state/configuration_depth_summary.csv','gradient_comparison':'results/task_metrics/prepared_state/gradient_metric_comparison.csv','objective':'results/task_metrics/prepared_state/objective_summary.csv'}};(ROOT/'verification/task_metrics_results.json').write_text(json.dumps(res,indent=2)+'\n')
